* { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  font-size: 18px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { font-weight: 500; letter-spacing: -0.005em; margin: 0; }
p { margin: 0; }
a { color: var(--green); text-decoration-thickness: 1px; text-underline-offset: 3px; }
a:hover { color: var(--green-deep); }

:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 3px;
}

.skip {
  position: absolute; left: 16px; top: -60px;
  background: var(--ink); color: var(--white);
  padding: 8px 12px; z-index: 10;
}
.skip:focus { top: 12px; }

/* ---------- header ---------- */

.site-head {
  max-width: var(--max);
  margin: 0 auto;
  padding: 22px var(--gutter) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.wordmark {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--ink); text-decoration: none;
  font-size: 22px; font-weight: 600; letter-spacing: -0.01em;
}
.site-nav { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; font-size: 16px; }
.site-nav a { color: var(--ink-2); text-decoration: none; }
.site-nav a:hover { color: var(--ink); text-decoration: underline; }
.site-nav .nav-cta {
  color: var(--green); border: 1px solid var(--green);
  padding: 6px 12px; border-radius: 2px;
}
.site-nav .nav-cta:hover { background: var(--green-tint); text-decoration: none; }

/* ---------- hero ---------- */

main > section {
  max-width: var(--max);
  margin: 0 auto;
  padding-left: var(--gutter);
  padding-right: var(--gutter);
}

.hero { padding-top: clamp(56px, 9vw, 120px); padding-bottom: clamp(40px, 6vw, 72px); }
.hero-who { color: var(--ink-2); font-size: 17px; margin-bottom: 18px; }
.hero h1 {
  font-size: clamp(34px, 5.2vw, 60px);
  line-height: 1.08;
  max-width: 19ch;
  text-wrap: balance;
}
.hero-sub {
  margin-top: 26px;
  max-width: var(--measure);
  font-size: clamp(18px, 1.6vw, 21px);
  color: var(--ink-2);
}
